void cFractalClipSphere000000000::FormulaCode(
	CVector4 &z, const sFractal *fractal, sExtendedAux &aux)
{
	// Sphere clipping
	CVector3 sphereCenter = CVector3(0.0, 0.0, 0.0);
	double radius = 2.0;
	
	// Distance to sphere surface
	double dist = (z - sphereCenter).Length() - radius;
	
	// Invert clipping (inside sphere)
	dist = -dist;
	// Smooth clipping
	double smoothFactor = 0.2;
	if (dist > -smoothFactor && dist < smoothFactor)
		dist = 0.5 * (dist + sqrt(dist*dist + smoothFactor*smoothFactor));
	
	// Apply clipping
	if (fabs(dist) < 0.1)
	{
		aux.dist = min(aux.dist, fabs(dist));
		aux.DE = min(aux.DE, fabs(dist));
	}
}
